        "jsCode": "// Format urgent emails
const urgent = $json.urgent || [];
const important = $json.important || [];

const formatted = {
  urgent_count: urgent.length,
  important_count: important.length,
  urgent_list: urgent.slice(0, 10).map(e => ({
    subject: e.subject,
    from: e.from,
    urgency_score: (e.urgencyScore * 100).toFixed(0),
    account: e.accountName,
    unread: !e.isRead
  })),
  important_list: important.slice(0, 10).map(e => ({
    subject: e.subject,
    from: e.from,
    importance_score: (e.importanceScore * 100).toFixed(0),
    reason: e.importanceReason?.[0]
  }))
};

return formatted;"
